LANGS = [("en", "English"), ("hi", "हिन्दी"), ("hry", "हरियाणवी"), ("pa", "ਪੰਜਾਬੀ")]


def table() -> dict:
    """key -> {en, hi, hry, pa}. Rows with a 5th element use it as the English template for a non-text key."""
    out: dict[str, dict] = {}
    for row in ROWS:
        key, hi, hry, pa = row[:4]
        en = row[4] if len(row) > 4 else key
        out[key] = {"en": en, "hi": hi, "hry": hry, "pa": pa}
    return out
